function selectedTSV(){let x=range(),z=[];for(let r=x.r1;r<=x.r2;r++){let q=[];for(let c=x.c1;c<=x.c2;c++)q.push(raw(addr(r,c)));z.push(q.join('\t'))}return z.join('\n')} function pasteText(t){let z={},rows=t.replace(/\r/g,'').split('\n');rows.forEach((line,i)=>(line.includes('\t')?line.split('\t'):line.split(/[,;]/)).forEach((v,j)=>z[addr(state.focus.r+i,state.focus.c+j)]=v));action(z,'Paste')}
function shiftFormula(v,dr,dc){return v.replace(/\b([A-Z]+)([1-9]\d*)\b/g,(_,c,r)=>addr(Math.max(1,+r+dr),Math.max(1,parseAddr(c+r).c+dc)))} function fill(dir){let x=range(),z={};if(dir==='down'){for(let c=x.c1;c<=x.c2;c++){let v=raw(addr(x.r1,c)),n=Number(v),step=Number(raw(addr(x.r1+1,c)))-n;for(let r=x.r1+1;r<=x.r2;r++)z[addr(r,c)]=v.startsWith('=')?shiftFormula(v,r-x.r1,0):Number.isFinite(step)&&step?String(n+step*(r-x.r1)):v}}else for(let r=x.r1;r<=x.r2;r++){let v=raw(addr(r,x.c1)),n=Number(v),step=Number(raw(addr(r,x.c1+1)))-n;for(let c=x.c1+1;c<=x.c2;c++)z[addr(r,c)]=v.startsWith('=')?shiftFormula(v,0,c-x.c1):Number.isFinite(step)&&step?String(n+step*(c-x.c1)):v}action(z,'Fill')}
function findMatches(){let q=$('findText').value.toLowerCase();return q?Object.keys(state.sheet.cells).filter(a=>raw(a).toLowerCase().includes(q)):[]} function findNext(){let m=findMatches();if(!m.length)return $('findStatus').textContent='No matches';let i=m.indexOf(addr(state.focus.r,state.focus.c)),p=parseAddr(m[(i+1)%m.length]);select(p.r,p.c);$('findStatus').textContent=`${(i+1)%m.length+1} of ${m.length}`} function replace(all){let m=findMatches(),targets=all?m:[m.includes(addr(state.focus.r,state.focus.c))?addr(state.focus.r,state.focus.c):m[0]],z={};if(!m.length)return showMessage('No matching cells');targets.forEach(a=>z[a]=raw(a).split($('findText').value).join($('replaceText').value));action(z,all?'Replace all':'Replace')}
function formulaHints(){let v=$('formula').value,box=$('suggestions');if(!v.startsWith('=')){box.style.display='none';return}let q=(/[A-Za-z]*$/.exec(v)||[''])[0].toUpperCase(),list=FUNCS.filter(x=>x.startsWith(q));box.innerHTML=list.map(x=>`<div class="suggestion" data-f="${x}">${x}</div>`).join('');let r=$('formula').getBoundingClientRect();box.style.cssText=`display:${list.length?'block':'none'};left:${r.left}px;top:${r.bottom}px`;document.querySelectorAll('.referenced').forEach(x=>x.classList.remove('referenced'));for(const m of v.matchAll(/[A-Z]+[1-9]\d*(?::[A-Z]+[1-9]\d*)?/gi)){let x=parseRangeText(m[0]);if(x)cellsIn(x).forEach(a=>$('cell-'+a)?.classList.add('referenced'))}} function clearReferences(){document.querySelectorAll('.referenced').forEach(x=>x.classList.remove('referenced'))} function insertReference(){if(!state.formulaEditing||!$('formula').value.startsWith('='))return false;let i=$('formula'),p=i.selectionStart,b=i.value.slice(0,p),m=/[A-Z]+[1-9]\d*(?::[A-Z]+[1-9]\d*)?$/i.exec(b),start=m?m.index:p;i.value=i.value.slice(0,start)+rangeAddress()+i.value.slice(p);i.focus();formulaHints();return true}
async function cellHistory(){let a=addr(state.focus.r,state.focus.c),d=await fetch(`/api/workbooks/${state.workbook.id}/history?sheetId=${state.sheet.id}&address=${a}`).then(r=>r.json());openDialog('History for '+a,d.length?d.map(x=>`<div class="historyItem"><b>${esc(x.userName)}</b>: ${esc(x.previousValue||'(blank)')} → ${esc(x.newValue||'(blank)')}<div class="muted">Revision ${x.revision} · ${new Date(x.changedAt).toLocaleString()}</div></div>`).join(''):'No saved changes.')}
async function revisions(){let d=await fetch(`/api/workbooks/${state.workbook.id}/revisions`).then(r=>r.json());openDialog('Revision history',d.map(x=>`<div class="revisionItem"><b>Revision ${x.number}</b> ${new Date(x.createdAt).toLocaleString()} <button data-preview="${x.number}">Preview & restore</button></div>`).join(''))} async function restoreRevision(n){let d=await fetch(`/api/workbooks/${state.workbook.id}/revisions/${n}`).then(r=>r.json()),z={},old=state.sheet.cells,now=d.sheets[0].cells;for(const a of new Set([...Object.keys(old),...Object.keys(now)]))z[a]=now[a]??'';action(z,'Restore revision '+n);$('sideDialog').close()} function openDialog(t,h){$('dialogTitle').textContent=t;$('dialogBody').innerHTML=h;$('sideDialog').showModal()}
function connect(){let p=location.protocol==='https:'?'wss':'ws';state.ws=new WebSocket(`${p}://${location.host}/live`);state.ws.onopen=join;state.ws.onmessage=e=>{let m=JSON.parse(e.data);if(m.type==='presence'){state.presence=m.sessions;renderPresence()}else if(m.type==='saved'&&m.userId!==state.userId)remoteSave(m)};state.ws.onclose=()=>setTimeout(connect,1200)} function join(){if(state.ws?.readyState===1&&state.workbook)state.ws.send(JSON.stringify({type:'join',workbookId:state.workbook.id,userId:state.userId,sessionId:state.sessionId,selection:rangeAddress()}))} function sendSelection(){if(state.ws?.readyState===1)state.ws.send(JSON.stringify({type:'selection',selection:rangeAddress()}))}
function renderPresence(){let o=state.presence.filter(x=>x.sessionId!==state.sessionId),counts={};state.presence.forEach(x=>counts[x.userName]=(counts[x.userName]||0)+1);$('presenceSummary').textContent=Object.entries(counts).map(([n,c])=>`${n}${c>1?' ('+c+' views)':''}`).join(', ');$('presence').innerHTML=o.length?o.map(x=>`<span class="person" style="--color:${x.color}">${esc(x.userName)} · ${esc(x.selection)}</span>`).join(''):'<span class="muted">Only you are viewing</span>';drawRemote()} function drawRemote(){$('remoteLayer').innerHTML=''}
function remoteSave(m){let local=new Set(changesFromSaved().map(x=>x.address));if(!state.dirty){state.workbook=clone(m.workbook);state.saved=clone(m.workbook);state.sheet=state.workbook.sheets[0]}else{m.changed.forEach(c=>{if(local.has(c.address))state.conflicts.add(c.address);else setRaw(c.address,c.value)});state.saved=clone(m.workbook)}state.revision=m.revision;$('revision').textContent='Revision '+m.revision;if(state.conflicts.size){setSaveState('Conflict','failed');showMessage('Remote edit conflict; your draft is preserved.',true)}render()}
